    if #spots == 0 then S.penFullUntil = os.clock() + 25; setText(UI.pnState, L["Pen · no free space"]); return false end
    local r = hrp()
    if r and yard and (r.Position - yard.Position).Magnitude > 45 then
        MV.tp(yard.Position + Vector3.new(0, yard.Size.Y / 2 + 4, 0)); task.wait(0.4)
    end
    local origin = plot:FindFirstChild("SpawnPoint") or yard
    local h = hum()
    local placed = 0
    for i, tool in ipairs(eggs) do
        if not RUNNING or not on("pn_place") or carrying() then break end
        local spot = spots[i]
        if not spot then break end
        if h and tool.Parent ~= lp.Character then pcall(h.EquipTool, h, tool); task.wait(0.2) end
        local ok, msg = invoke("EggRemotes.PlaceEgg", origin.CFrame:ToObjectSpace(CFrame.new(spot)))
        if ok then
            placed = placed + 1; S.placed = S.placed + 1
        else
            MSG.set(tostring(msg or "Can't place"))
            S.penFullUntil = os.clock() + 20
            break
        end
        task.wait(0.35)
    end
    if h then pcall(h.UnequipTools, h) end
    if placed > 0 then setText(UI.pnState, L["Pen · placed "] .. placed) end
    return placed > 0
end
function PEN.wantsPlace()
    return on("pn_place") and os.clock() > (S.penFullUntil or 0) and #PEN.tools("AssetEgg") > 0 and myPlot() ~= nil
end
function PEN.hatchTick()
    if not on("pn_hatch") then return end
