        if not RUNNING then return end
        if e:GetAttribute("Ready") == true and e:GetAttribute("Hatching") ~= true then
            local uid = e:GetAttribute("Uid")
            if uid then
                local ok, msg = invoke("EggRemotes.HatchEgg", uid)
                if ok then S.hatched = S.hatched + 1; S.penFullUntil = 0 else MSG.set(tostring(msg or "")) end
                task.wait(0.4)
            end
        end
    end
end
function PEN.bestTick()
