end
local ST = { blk = {} }
function ST.carrySpeed()
    return math.max(16, realSpeed() * (tonumber(val("st_mul", 1.25)) or 1.25))
end
function ST.canEscape(z)
    return z ~= nil and z.need <= baseSpeed() + 0.05
end
function ST.zoneOK(zn, zmap)
    local z = zmap[zn]
    if not z then return false end
    if val("st_zmode", "Auto") == "Selected Zones" then
        local s = msel("st_zones")
        if not s then return false end
        local picked = false
        for l in pairs(s) do if ST.zmap and ST.zmap[l] == zn then picked = true end end
        return picked and ST.reachable(z)
    end
    return ST.reachable(z)
end
ST.zoneBad, ST.zoneFails = {}, {}
function ST.instant() return val("st_method", "Instant") == "Instant" end
function ST.relayOK(z)
    return not z.blink and z.guard <= ST.carrySpeed() * 1.05
end
function ST.reachable(z)
    if (ST.zoneBad[z.n] or 0) > os.clock() then return false end
    return ST.instant() or ST.canEscape(z) or ST.relayOK(z)
end
function ST.double(state)
    if ST.dbl then pcall(function() ST.dbl:Destroy() end); ST.dbl = nil end
    if not state then return end
    local c = lp.Character
    if not c then return end
    local was = c.Archivable
    c.Archivable = true
    local ok, copy = pcall(function() return c:Clone() end)
    c.Archivable = was
    if not (ok and copy) then return end
    for _, d in ipairs(copy:GetDescendants()) do
        if d:IsA("LuaSourceContainer") or d:IsA("Humanoid") or d:IsA("ForceField") or d:IsA("Sound") then
            pcall(function() d:Destroy() end)
        elseif d:IsA("BasePart") then
            d.Anchored = true; d.CanCollide = false; d.CanQuery = false; d.CanTouch = false
            d.LocalTransparencyModifier = 0
        elseif d:IsA("Decal") then
            d.LocalTransparencyModifier = 0
        end
    end
    copy.Name = HttpService:GenerateGUID(false):sub(1, 8)
    copy.Parent = Workspace.CurrentCamera
    ST.dbl = copy
end
function ST.veil(state)
    local c = lp.Character
    if state then
        ST.veilCam = Workspace.CurrentCamera.CFrame
        ST.veilUntil = os.clock() + 6
        pcall(ST.double, true)
    else
        if ST.veilCam then ST.veilRestore = true end
        ST.veilCam = nil
        pcall(ST.double, false)
    end
    for _, d in ipairs(c and c:GetDescendants() or {}) do
        if d:IsA("BasePart") or d:IsA("Decal") then d.LocalTransparencyModifier = state and 1 or 0 end
    end
    if state then
        ST.eggParts = {}
        local ce = Workspace:FindFirstChild("CarriedEggs")
        for _, m in ipairs(ce and ce:GetChildren() or {}) do
            if m:GetAttribute("HeldBy") == lp.UserId then
                for _, d in ipairs(m:GetDescendants()) do
                    if d:IsA("BasePart") or d:IsA("Decal") then d.LocalTransparencyModifier = 1; ST.eggParts[#ST.eggParts + 1] = d end
                end
            end
        end
    else
        for _, d in ipairs(ST.eggParts or {}) do pcall(function() d.LocalTransparencyModifier = 0 end) end
        ST.eggParts = nil
        local le = Workspace:FindFirstChild("LooseEggs")
        for _, m in ipairs(le and le:GetChildren() or {}) do
            for _, d in ipairs(m:GetDescendants()) do
                if (d:IsA("BasePart") or d:IsA("Decal")) and d.LocalTransparencyModifier > 0 then d.LocalTransparencyModifier = 0 end
            end
        end
    end
end
function ST.veilStep()
    local cam = Workspace.CurrentCamera
    if ST.veilCam and os.clock() > (ST.veilUntil or 0) then ST.veil(false) end
    if ST.veilCam then
        if cam.CameraType ~= Enum.CameraType.Scriptable then cam.CameraType = Enum.CameraType.Scriptable end
        cam.CFrame = ST.veilCam
    elseif ST.veilRestore then
        ST.veilRestore = nil
        cam.CameraType = Enum.CameraType.Custom
        local h = hum()
        if h then cam.CameraSubject = h end
    end
end
onClean(function() pcall(ST.veil, false); pcall(ST.veilStep) end)
function ST.depth()
    local rc = ReplicatedStorage:FindFirstChild("RespawnConfig")
    local floor = -200
    for _, v in pairs(rc and rc:GetAttributes() or {}) do
        if type(v) == "number" and v < -20 then floor = v end
    end
    return floor - 30
end
function ST.quickHome()
    local r = hrp()
    if not r then return false end
    local creature = ST.curCreature
    local x, z = r.Position.X, r.Position.Z
    local goal = ST.depth()
    local step = math.max(30, r.Position.Y - goal)
    MV.gliding = true
    pcall(ST.veil, true)
    local t0 = os.clock()
    while RUNNING and carrying() and os.clock() - t0 < 3 do
        r = hrp()
        if not r then break end
        local ny = math.max(goal, r.Position.Y - step)
        r.CFrame = CFrame.new(x, ny, z)
        r.AssemblyLinearVelocity = ny <= goal and Vector3.zero or Vector3.new(0, -step * 4, 0)
        RunService.Heartbeat:Wait()
    end
    if carrying() then MV.gliding = false; pcall(ST.veil, false); return false end
    t0 = os.clock()
    while RUNNING and os.clock() - t0 < 4 do
        r = hrp()
        if r and r.Position.Y > goal + 150 and r.Position.Z > lineZ() then break end
        if r and r.Position.Z < lineZ() and r.Position.Y < goal + 50 then
            r.CFrame = CFrame.new(x, goal, z)
            r.AssemblyLinearVelocity = Vector3.zero
        end
        RunService.Heartbeat:Wait()
    end
    MV.gliding = false
    pcall(ST.veil, false)
    r = hrp()
    if not (r and r.Position.Z > lineZ()) then return false end
    setText(UI.stState, L["Steal · picking it up"])
    local m = ST.settledLoose(r.Position, creature)
    if not m then
        task.wait(0.6)
        m = ST.findLoose(r.Position, creature)
    end
    if not (m and ST.regrab(m)) then return false end
    t0 = os.clock()
    while carrying() and os.clock() - t0 < 4 do task.wait(0.1) end
    return not carrying()
end
function ST.noteResult(zn, banked)
    if not zn then return end
    if banked then ST.zoneFails[zn] = 0; return end
    ST.zoneFails[zn] = (ST.zoneFails[zn] or 0) + 1
    if ST.zoneFails[zn] >= 2 then
        ST.zoneFails[zn] = 0
        ST.zoneBad[zn] = os.clock() + 600
        MSG.set("Zone " .. zn .. " skipped for 10 min")
    end
end
function ST.topZone()
    local best = 0
    for _, z in ipairs(ZONE.list()) do if ST.reachable(z) then best = math.max(best, z.n) end end
    return best
end
function ST.score(egg, r)
    local mode = val("st_prio", "Best Value")
    if mode == "Biggest" then return EGG.size(egg) * 1e6 + (tonumber(egg:GetAttribute("Zone")) or 0)
    elseif mode == "Highest Zone" then return (tonumber(egg:GetAttribute("Zone")) or 0) * 1e9 + EGG.value(egg) / 1e30
    elseif mode == "Nearest" then
        local p = posOf(egg); return p and r and -(p - r.Position).Magnitude or -1e9
    end
    return EGG.value(egg)
end
function ST.pick()
    local r = hrp()
    local zmap = ZONE.byN()
    local rarSet, mutSet, minSize = msel("st_rar"), msel("st_mut"), minSizeOf("st_size")
    local now = os.clock()
    if S.snipe and S.snipe.Parent and S.snipe:GetAttribute("HeldBy") == nil and ST.zoneOK(tonumber(S.snipe:GetAttribute("Zone")) or 0, zmap) then
        return S.snipe
    end
    S.snipe = nil
    local best, bestScore = nil, -math.huge
    for _, egg in ipairs(EGG.wild(on("st_loose"))) do
        if (ST.blk[egg] or 0) < now then
            local zn = tonumber(egg:GetAttribute("Zone")) or 0
            if ST.zoneOK(zn, zmap) and EGG.match(egg, rarSet, minSize, mutSet) and egg:FindFirstChild("EggPrompt", true) then
                local s = ST.score(egg, r)
                if s > bestScore then best, bestScore = egg, s end
            end
        end
    end
    return best
end
function ST.sealedWait()
    local t0 = os.clock()
    while RUNNING and Workspace:GetAttribute("EggWallSealed") == true and os.clock() - t0 < 20 do
        setText(UI.stState, L["Steal · gate closed, waiting"])
        task.wait(0.25)
    end
end
function ST.findLoose(near, creature)
    local le = Workspace:FindFirstChild("LooseEggs")
    local best, bd
    for _, m in ipairs(le and le:GetChildren() or {}) do
        if m:IsA("Model") and m:GetAttribute("HeldBy") == nil and (not creature or m:GetAttribute("Creature") == creature) then
            local p = posOf(m)
            if p then
                local d = (p - near).Magnitude
                if d < 160 and (not bd or d < bd) then best, bd = m, d end
            end
        end
    end
    return best
end
function ST.holdPrompt(pr)
    if not pr then return false end
    pcall(function() pr:InputHoldBegin() end)
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < pr.HoldDuration + 0.15 and not carrying() do task.wait(0.03) end
    pcall(function() pr:InputHoldEnd() end)
    t0 = os.clock()
    while RUNNING and not carrying() and os.clock() - t0 < 1.5 do task.wait(0.05) end
    return carrying()
end
function ST.approachOf(p)
    local lz = lineZ()
    if p.Z < lz and lz - p.Z < 9 then return Vector3.new(p.X, p.Y, lz + 2.5) end
    return p
end
function ST.crossLine()
    local r = hrp()
    local lz = lineZ()
    if not (r and carrying() and r.Position.Z < lz + 2) then return end
    MV.glide(Vector3.new(r.Position.X, 0, lz + 8), function() return math.max(MV.zoneSpeed(), 120) end, carrying, 3)
end
function ST.regrab(m)
    local started = os.clock()
    while RUNNING and os.clock() - started < 8 do
        if not (m and m.Parent) or m:GetAttribute("HeldBy") ~= nil then return false end
        setText(UI.stState, L["Steal · picking it up"])
        local t0 = os.clock()
        while RUNNING and m.Parent and os.clock() - t0 < 4 do
            local p, r = posOf(m), hrp()
            if not (p and r) then return false end
            local a = ST.approachOf(p)
            if (Vector3.new(r.Position.X, 0, r.Position.Z) - Vector3.new(a.X, 0, a.Z)).Magnitude <= 3 then break end
            MV.glide(a, function() return ST.carrySpeed() end, function()
                local q = posOf(m)
                if not q then return false end
                local aa = ST.approachOf(q)
                return (Vector3.new(hrp().Position.X, 0, hrp().Position.Z) - Vector3.new(aa.X, 0, aa.Z)).Magnitude > 3
            end, 1.5)
        end
        if not m.Parent then return false end
        local r = hrp()
        if r then r.AssemblyLinearVelocity = Vector3.zero end
        if ST.holdPrompt(m:FindFirstChild("EggPrompt", true) or m:FindFirstChildWhichIsA("ProximityPrompt", true)) then
            ST.crossLine()
            return true
        end
        task.wait(0.15)
    end
    return false
end
function ST.myGuards()
    local out = {}
    local ag = Workspace:FindFirstChild("ActiveGuardians")
    for _, g in ipairs(ag and ag:GetChildren() or {}) do
        if g:GetAttribute("ChaserAggroUserId") == lp.UserId or (ST.curZone and tonumber(g:GetAttribute("Zone")) == ST.curZone) then out[#out + 1] = g end
    end
    return out
end
function ST.guardGap()
    local r = hrp()
    if not r then return math.huge end
    local best = math.huge
    for _, g in ipairs(ST.myGuards()) do
        local gp = posOf(g)
        if gp then best = math.min(best, (gp - r.Position).Magnitude) end
    end
    return best
end
function ST.segmentCond(t0)
    local closeSince, lastCheck, gap = nil, 0, math.huge
    local limit = tonumber(val("st_carry_t", 3)) or 3
    return function()
        if not (carrying() and RUNNING) then return false end
        local now = os.clock()
        if now - t0 > limit then return false end
        if now - lastCheck > 0.15 then lastCheck = now; gap = ST.guardGap() end
        if gap < 30 then
            closeSince = closeSince or now
            if now - closeSince > 1.2 then return false end
        else
            closeSince = nil
        end
        return true
    end
end
function ST.settledLoose(near, creature)
    local t0 = os.clock()
    local m
    while RUNNING and os.clock() - t0 < 1.5 do
        m = ST.findLoose(near, creature)
        if m then break end
        task.wait(0.05)
    end
    if not m then return nil end
    t0 = os.clock()
    while RUNNING and m.Parent and os.clock() - t0 < 1.2 do
        local part = partOf(m)
        if not part or part.AssemblyLinearVelocity.Magnitude < 3 then break end
        task.wait(0.05)
    end
    return m.Parent and m or nil
end
function ST.runHome()
    local r = hrp()
    if not r then return false end
    local lz = lineZ()
    local lx = laneX()
    local tx = math.clamp(r.Position.X, lx - 50, lx + 50)
    local before = bagCount()
    local creature = ST.curCreature
    local relays = 0
    setText(UI.stState, L["Steal · bringing it home"])
    if ST.instant() and r.Position.Z < lz then
        local ok = ST.quickHome()
        if ok then
            S.stolen = S.stolen + 1
            setText(UI.stState, L["Steal · banked ("] .. S.stolen .. ")")
            return true
        end
        if not carrying() then
            local m = ST.findLoose((hrp() or r).Position, creature)
            if m and ST.regrab(m) then
                local t1 = os.clock()
                while carrying() and os.clock() - t1 < 4 do task.wait(0.1) end
                if not carrying() and bagCount() > before then S.stolen = S.stolen + 1; return true end
            end
            return false
        end
        r = hrp() or r
        tx = math.clamp(r.Position.X, lx - 50, lx + 50)
    end
    for _ = 1, 80 do
        if not (RUNNING and carrying()) then break end
        r = hrp()
        if not r then break end
        if r.Position.Z > lz + 2 then break end
        local relay = (ST.instant() or not ST.canEscape(ZONE.byN()[ST.curZone or 0])) and ((lz + 14) - r.Position.Z) > ST.carrySpeed() * 1.5
        if Workspace:GetAttribute("EggWallSealed") == true and r.Position.Z > lz - 25 then ST.sealedWait() end
        local cond = relay and ST.segmentCond(os.clock()) or function() return carrying() and RUNNING end
        MV.glide(Vector3.new(tx, 0, lz + 14), ST.carrySpeed, cond, 240)
        if not carrying() then break end
        r = hrp()
        if r and r.Position.Z > lz + 2 then break end
        if relay then
            local dropAt = (hrp() or r).Position
            local rr = hrp()
            if rr then rr.AssemblyLinearVelocity = Vector3.zero end
            fire("EggRemotes.DropCarriedEgg")
            local m = ST.settledLoose(dropAt, creature)
            if not (m and ST.regrab(m)) then setText(UI.stState, m and L["Steal · regrab failed"] or L["Steal · egg not found"]); break end
            relays = relays + 1
            setText(UI.stState, L["Steal · bringing it home ("] .. relays .. ")")
        end
    end
    local t0 = os.clock()
    while carrying() and os.clock() - t0 < 4 do task.wait(0.1) end
    local rr = hrp()
    local banked = (not carrying()) and rr ~= nil and rr.Position.Z > lz and (bagCount() >= before)
    if banked then
        S.stolen = S.stolen + 1
        setText(UI.stState, L["Steal · banked ("] .. S.stolen .. ")")
    end
    return banked
end
function ST.tripTime(egg)
    local r, p = hrp(), posOf(egg)
    if not (r and p) then return 999 end
    local out = (p - r.Position).Magnitude / MV.zoneSpeed()
    local back = ST.instant() and 5 or math.max(0, lineZ() - p.Z) / (ST.carrySpeed() * 0.6)
    return out + back + 4
end
function ST.grab(egg)
    local r = hrp()
    local pr = egg:FindFirstChild("EggPrompt", true)
    local anchor = pr and pr.Parent
    local p = (anchor and anchor:IsA("Attachment") and anchor.WorldPosition) or posOf(egg)
    if not (r and p) then return false end
    setText(UI.stState, L["Steal · "] .. EGG.label(egg))
    local keep = function() return egg.Parent ~= nil and egg:GetAttribute("HeldBy") == nil and not isNight() and on("st_on") ~= false end
    local side = Vector3.new(r.Position.X - p.X, 0, r.Position.Z - p.Z)
    side = side.Magnitude > 0.1 and side.Unit or Vector3.new(1, 0, 0)
    local dist = Vector3.new(r.Position.X - p.X, 0, r.Position.Z - p.Z).Magnitude
    if dist > 70 then
        if not MV.go(p + side * 60, keep, 120) then return false end
    end
    if not keep() then return false end
    if not MV.glide(p + side * 2.5, function() return math.max(16, realSpeed()) end, keep, 15) and not keep() then return false end
    local rr = hrp()
    if rr then rr.AssemblyLinearVelocity = Vector3.zero end
    local settle = tonumber(val("st_settle", 1.5)) or 1.5
    local t0 = os.clock()
    while RUNNING and keep() and os.clock() - t0 < settle do
        rr = hrp()
        if rr then rr.AssemblyLinearVelocity = Vector3.zero end
        task.wait(0.05)
    end
    if not keep() then return false end
    pr = egg:FindFirstChild("EggPrompt", true)
    if not pr then return false end
    ST.curCreature = egg:GetAttribute("Creature")
    ST.curZone = tonumber(egg:GetAttribute("Zone"))
    return ST.holdPrompt(pr)
end
function ST.trip(egg)
    if MV.tainted() and not MV.clearTaint() then return false end
    if isNight() or toNight() < ST.tripTime(egg) then
        setText(UI.stState, L["Steal · night soon, waiting"])
        return false
    end
    local zn = tonumber(egg:GetAttribute("Zone"))
    if ST.grab(egg) then
        ST.fails = 0
        local ok = ST.runHome()
        ST.noteResult(zn, ok)
        if not ok and not carrying() then setText(UI.stState, L["Steal · got caught"]) end
        local lim = tonumber(val("st_stop", 0)) or 0
        if lim > 0 and S.stolen >= lim then
            pcall(function() Toggles.st_on:SetValue(false) end)
            notify(L["Stolen "] .. S.stolen .. L[" eggs · stopped"])
        end
        return true
    end
    ST.blk[egg] = os.clock() + 20
    return false
end
local SELL = { last = 0 }
function SELL.toolMap()
    local m = {}
    for _, holder in ipairs({ lp:FindFirstChildOfClass("Backpack"), lp.Character }) do
        for _, t in ipairs(holder and holder:GetChildren() or {}) do
            local u = t:IsA("Tool") and t:GetAttribute("Uid")
            if u then m[tostring(u)] = t end
        end
    end
    return m
end
function SELL.pick(list)
    local kinds = msel("sl_kinds") or {}
    local keepRar = msel("sl_keep_rar") or {}
    local keepMut = on("sl_keep_mut")
    local maxRate = parseNum(val("sl_max_rate", ""))
    local keepTop = math.floor(tonumber(val("sl_keep_top", 3)) or 0)
    local tools = SELL.toolMap()
    local pets = {}
    for _, it in ipairs(list) do if it.kind == "Pet" then pets[#pets + 1] = it end end
    table.sort(pets, function(a, b) return (tonumber(a.rate) or 0) > (tonumber(b.rate) or 0) end)
    local top = {}
    for i = 1, math.min(keepTop, #pets) do top[pets[i].uid] = true end
    local out, total = {}, 0
    for _, it in ipairs(list) do
        local want = (it.kind == "Egg" and kinds.Eggs) or (it.kind == "Pet" and kinds.Pets)
        if want and not top[it.uid] then
            local t = tools[tostring(it.uid)]
            local mutated = type(it.mutations) == "string" and it.mutations ~= ""
            local special = t and (t:GetAttribute("Premium") == true or t:GetAttribute("Universal") ~= nil)
            local rar = t and (EGG.rarity(t)) or nil
            local rateOK = (not maxRate) or (tonumber(it.rate) or 0) < maxRate
            if not (keepMut and mutated) and not special and not (rar and keepRar[rar]) and rateOK then
                out[#out + 1] = it.uid
                total = total + (tonumber(it.price) or 0)
            end
        end
    end
    return out, total
end
function SELL.run(force)
    local list = invoke("SellRemotes.ListSellable")
    if type(list) ~= "table" then return 0 end
    local uids, total = SELL.pick(list)
    if #uids == 0 then
        if force then setText(UI.slState, L["Sell · nothing to sell"]) end
        return 0
    end
    local back
    local r = hrp()
    local shop = Workspace:FindFirstChild("SELL")
    local spot = shop and posOf(shop:FindFirstChild("DialogueAnchor", true) or shop)
    if r and spot and (r.Position - spot).Magnitude > 25 and not carrying() then
        back = r.CFrame
        MV.tp(spot + Vector3.new(0, 3, 4)); task.wait(0.4)
    end
    local ok, cash, count = invoke("SellRemotes.SellItems", uids)
    if back and on("sl_return") and not carrying() then task.wait(0.2); MV.tp(back.Position) end
    if ok then
