                end
            end
        end
    end
end
function RW.codes()
    local list, seen = {}, {}
    local function add(c)
        c = tostring(c or ""):gsub("%s", "")
        if c ~= "" and c:upper() ~= "CODE:" and not seen[c:upper()] then seen[c:upper()] = true; list[#list + 1] = c end
    end
    for _, m in ipairs(Workspace:GetChildren()) do
        local hasCode, texts = false, {}
        for _, d in ipairs(m:GetDescendants()) do
            if d:IsA("TextLabel") then
                local t = tostring(d.Text)
                if t:upper():match("^%s*CODE:?%s*$") then hasCode = true elseif t:match("^%s*[%w]+%s*$") then texts[#texts + 1] = t end
            end
        end
        if hasCode then for _, t in ipairs(texts) do add(t) end end
    end
    for _, c in ipairs({ "ENDGAME", "1MVISITS", "HASHTAGS", "RANDOMBAT", "DEMONIC", "STRONGBAT", "SHOWSPEED", "TUNG" }) do add(c) end
    local okN = 0
    for _, c in ipairs(list) do
        local ok = invoke("CodesRemotes.Redeem", c)
        if ok then okN = okN + 1 end
        task.wait(0.6)
    end
    return okN, #list
end
