local RAG = { off = {} }
function RAG.apply(state)
    if type(getconnections) ~= "function" then return end
    for _, path in ipairs({ "RagdollRemotes.Push", "RagdollService.LocalPlayerRagdollRemote" }) do
        local r = rem(path)
        if r and r:IsA("RemoteEvent") then
            local ok, cons = pcall(getconnections, r.OnClientEvent)
            for _, c in ipairs(ok and cons or {}) do
                if state and not RAG.off[c] then if pcall(function() c:Disable() end) then RAG.off[c] = true end
                elseif not state and RAG.off[c] then pcall(function() c:Enable() end); RAG.off[c] = nil end
            end
        end
    end
end
function RAG.parts()
    local c = lp.Character
    if not c then return {}, {} end
    if RAG.char ~= c or os.clock() - (RAG.scanAt or 0) > 5 then
        RAG.char, RAG.scanAt = c, os.clock()
        RAG.joints, RAG.sockets = {}, {}
        for _, d in ipairs(c:GetDescendants()) do
            if d:IsA("AnimationConstraint") or d:IsA("Motor6D") then RAG.joints[#RAG.joints + 1] = d
            elseif d:IsA("BallSocketConstraint") or d:IsA("HingeConstraint") then RAG.sockets[#RAG.sockets + 1] = d end
        end
    end
    return RAG.joints, RAG.sockets
