function RAG.step()
    if not on("pv_norag") then return end
    local h, r = hum(), hrp()
    if not (h and r) or h.Health <= 0 then return end
    local joints, sockets = RAG.parts()
    local hit = false
    for _, j in ipairs(joints) do
        if j.Parent and not j.Enabled then j.Enabled = true; hit = true end
    end
    local st = h:GetState()
    if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown then hit = true end
    if hit then
        for _, s in ipairs(sockets) do if s.Parent and s.Enabled then s.Enabled = false end end
        h.PlatformStand = false
        h.AutoRotate = true
        pcall(function() h:ChangeState(Enum.HumanoidStateType.GettingUp) end)
        RAG.calmUntil = os.clock() + 0.6
    end
    if os.clock() < (RAG.calmUntil or 0) then
        r.AssemblyLinearVelocity = Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
    elseif not (on("mv_fly") or MV.gliding) and r.AssemblyLinearVelocity.Magnitude > math.max(250, realSpeed() * 3) then
        r.AssemblyLinearVelocity = Vector3.zero
    end
end
