    local ids = {}
    if ok and type(res) == "table" and type(res.data) == "table" then
        for _, s in ipairs(res.data) do
            if s.id ~= game.JobId and (tonumber(s.playing) or 0) < (tonumber(s.maxPlayers) or 6) then ids[#ids + 1] = s.id end
        end
    end
    if #ids == 0 then notify(L["No other servers found"]); return end
    pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, ids[math.random(1, #ids)], lp) end)
end
function PL.step(dt)
    local h, r = hum(), hrp()
    if not (h and r) then return end
    local free = not carrying() and not MV.inZone(r.Position)
    if on("mv_speed") and free then
        if PL.saved.ws == nil then PL.saved.ws = h.WalkSpeed end
        h.WalkSpeed = tonumber(val("mv_speed_v", 60)) or 60
    elseif PL.saved.ws ~= nil then
        h.WalkSpeed = PL.saved.ws; PL.saved.ws = nil
    end
    if on("mv_fly") and free then
        local cam = Workspace.CurrentCamera
        local mv = Vector3.zero
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then mv = mv + cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then mv = mv - cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then mv = mv + cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then mv = mv - cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then mv = mv + Vector3.yAxis end
        if UserInputService:IsKeyDown(Enum.KeyCode.Q) then mv = mv - Vector3.yAxis end
        if h.MoveDirection.Magnitude > 0.05 and mv.Magnitude < 0.05 then mv = h.MoveDirection end
        local sp = tonumber(val("mv_fly_v", 70)) or 70
        r.AssemblyLinearVelocity = (mv.Magnitude > 0 and mv.Unit or Vector3.zero) * sp
        h:ChangeState(Enum.HumanoidStateType.Freefall)
    end
end
function PL.noclip()
    if not on("mv_noclip") then return end
    local c = lp.Character
    for _, p in ipairs(c and c:GetDescendants() or {}) do
        if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
    end
end
onClean(function()
    local h = hum()
    if h and PL.saved.ws ~= nil then h.WalkSpeed = PL.saved.ws end
end)
local PERF = {}
function PERF.gfx(state)
    if state and not PERF.on then
        PERF.on = true
        PERF.saved = { shadows = Lighting.GlobalShadows, fx = setmetatable({}, { __mode = "k" }) }
        Lighting.GlobalShadows = false
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        task.spawn(function()
            local n = 0
            for _, v in ipairs(Workspace:GetDescendants()) do
                if not PERF.on then return end
                if (v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam") or v:IsA("Smoke") or v:IsA("Fire") or v:IsA("Sparkles")) and v.Enabled then
                    v.Enabled = false; PERF.saved.fx[v] = true
                end
                n = n + 1; if n % 500 == 0 then task.wait() end
            end
        end)
    elseif not state and PERF.on then
        PERF.on = false
        local s = PERF.saved
        if s then
            Lighting.GlobalShadows = s.shadows
            for v in pairs(s.fx) do pcall(function() v.Enabled = true end) end
        end
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic end)
        PERF.saved = nil
    end
end
function PERF.popups()
    if not on("wd_nopop") then return end
    local pg = lp:FindFirstChild("PlayerGui")
    local g = pg and pg:FindFirstChild("SpeedTollGui")
    if not g then return end
    for _, n in ipairs({ "Offer", "Warning" }) do
        local f = g:FindFirstChild(n)
        if f and f:IsA("GuiObject") and f.Visible then f.Visible = false end
    end
end
function PERF.tick()
    pcall(PERF.popups)
    if on("pf_cap") then
        local cap = tonumber(val("pf_fps", 30)) or 30
        if PERF.cap ~= cap and type(setfpscap) == "function" then pcall(setfpscap, cap); PERF.cap = cap end
    elseif PERF.cap then
        if type(setfpscap) == "function" then pcall(setfpscap, 240) end
        PERF.cap = nil
    end
    local nr = on("pf_norender") or false
    if nr ~= PERF.nr then PERF.nr = nr; pcall(function() RunService:Set3dRenderingEnabled(not nr) end) end
    if on("wd_bright") then
        if not PERF.light then PERF.light = { Lighting.Brightness, Lighting.GlobalShadows, Lighting.Ambient, Lighting.OutdoorAmbient } end
        Lighting.Brightness = 2.5; Lighting.GlobalShadows = false
        Lighting.Ambient = Color3.fromRGB(180, 180, 180); Lighting.OutdoorAmbient = Color3.fromRGB(180, 180, 180)
    elseif PERF.light then
        local v = PERF.light; PERF.light = nil
        Lighting.Brightness, Lighting.GlobalShadows, Lighting.Ambient, Lighting.OutdoorAmbient = v[1], v[2], v[3], v[4]
    end
    if on("wd_fog") then
        if not PERF.fog then PERF.fog = { Lighting.FogEnd, Lighting.FogStart } end
        Lighting.FogEnd = 1e6; Lighting.FogStart = 1e6
    elseif PERF.fog then
        Lighting.FogEnd, Lighting.FogStart = PERF.fog[1], PERF.fog[2]; PERF.fog = nil
    end
end
onClean(function()
    PERF.gfx(false)
    if PERF.cap and type(setfpscap) == "function" then pcall(setfpscap, 240) end
    if PERF.nr then pcall(function() RunService:Set3dRenderingEnabled(true) end) end
    if PERF.light then local v = PERF.light; Lighting.Brightness, Lighting.GlobalShadows, Lighting.Ambient, Lighting.OutdoorAmbient = v[1], v[2], v[3], v[4] end
    if PERF.fog then Lighting.FogEnd, Lighting.FogStart = PERF.fog[1], PERF.fog[2] end
end)
local BRAIN = {}
function BRAIN.step()
    if not alive() then return end
    if carrying() and (on("st_on") or on("pv_hunt")) then ST.runHome(); return end
    if EV.rift() then return end
    if PEN.wantsPlace() then if PEN.place() then return end end
    if SELL.due() then SELL.run(false); return end
    if EV.crate() then return end
    if PVP.hunt() then return end
    if on("st_on") then
        local egg = ST.pick()
        if egg and not isNight() and toNight() >= ST.tripTime(egg) then ST.trip(egg); return end
        setText(UI.stState, egg and L["Steal · night soon, waiting"] or L["Steal · waiting for eggs"])
        if not on("fd_on") then
            local r = hrp()
            if r and MV.inZone(r.Position) and (isNight() or toNight() < 15) then
                MV.go(Vector3.new(r.Position.X, 0, lineZ() + 10), function() return not carrying() end, 60)
            end
            return
        end
    end
    if FOOD.step() then return end
end
