local function bigEgg(payload)
    if type(payload) ~= "table" then return end
    local list = payload[1] and payload or { payload }
    local minS = minSizeOf("be_min")
    for _, e in ipairs(list) do
        if type(e) == "table" and typeof(e.egg) == "Instance" then
            local mul = tonumber(e.mul) or EGG.size(e.egg)
            if on("be_alert") then notify(string.format(L["Big egg x%s · zone %s"], short(mul), tostring(e.zone or e.egg:GetAttribute("Zone") or "?"))) end
            if on("be_auto") and mul >= minS and (not S.snipe or EGG.size(S.snipe) < mul) then S.snipe = e.egg end
        end
    end
end
task.spawn(function()
    local r = rem("EggRemotes.BigEgg")
    if r and r:IsA("RemoteEvent") then track(r.OnClientEvent:Connect(function(p) pcall(bigEgg, p) end)) end
    local toll = rem("GuardRemotes.SpeedToll")
    if toll and toll:IsA("RemoteEvent") then
        track(toll.OnClientEvent:Connect(function(t)
            if type(t) == "table" then pcall(MSG.set, string.format("Zone %s needs %s speed", tostring(t.zone), tostring(t.need))) end
        end))
    end
end)
local function restockText()
    local a = tonumber(Workspace:GetAttribute("EggCycleAnchorAt"))
    local c = tonumber(Workspace:GetAttribute("EggCycleSeconds")) or 300
    if not a or c <= 0 then
        local at = tonumber(Workspace:GetAttribute("EggWallOpensAt"))
        if at then return "Restock · " .. math.max(0, math.floor(at - Workspace:GetServerTimeNow())) .. "s" end
        return L["Restock · -"]
    end
    local now = Workspace:GetServerTimeNow()
    local left = c - ((now - a) % c)
    return string.format("Restock · %d:%02d", left // 60, math.floor(left % 60))
end
