                setText(UI.stZone, string.format(L["Zones 1-%d · %d spd"], ST.topZone(), math.floor(baseSpeed())))
            end
            setText(UI.beState, restockText())
            setText(UI.ssA, string.format(L["Stolen %d · Hatched %d"], S.stolen, S.hatched))
            setText(UI.ssB, string.format(L["Sold %d · $%s"], S.sold, short(S.soldCash)))
            if (S.money0 or 0) <= 0 then S.money0 = money() end
            if (S.speed0 or 0) <= 0 then S.speed0 = stat("RunSpeed") end
            setText(UI.ssC, L["Money +$"] .. short(money() - S.money0))
            setText(UI.ssD, L["Speed +"] .. short(stat("RunSpeed") - S.speed0))
            if S.msg ~= "" and os.clock() - S.msgAt < 60 then setText(UI.ssMsg, L["Game · "] .. S.msg) end
            local plot = myPlot()
            setText(UI.upState, string.format(L["Pen $%s · Table $%s"], short(UP.cost(plot, "PenUpgradeSign") or 0), short(UP.cost(plot, "TableUpgradeSign") or 0)))
            setText(UI.hsState, L["Coins · "] .. short(lp:GetAttribute("HackerCoins") or 0))
            local fe = lp:GetAttribute("FreeEggReady") == true and "ready" or (tostring(lp:GetAttribute("FreeEggLeftToday") or "-") .. " left today")
            setText(UI.rwState, L["Free egg · "] .. fe)
